import{_ as a,o as t,c as e,a5 as r}from"./chunks/framework.Cooo9kuv.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"批量docx文档插入图片工具","日期":"2026-04-30T00:00:00.000Z","修改日期":"2026-04-30T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["定制类程序"],"标签":["docx插入图片","Word图片插入工具","Word批量插入图片","Word文档批量插入图片","办公文档工具","图片自动匹配","批量Word文档处理","按序号插入图片","文档图片匹配工具","文档图片批量处理"]},"headers":[],"relativePath":"md/定制类程序/批量docx文档插入图片工具.md","filePath":"md/定制类程序/批量docx文档插入图片工具.md"}'),l={name:"md/定制类程序/批量docx文档插入图片工具.md"};function n(s,o,i,d,c,p){return t(),e("div",null,[...o[0]||(o[0]=[r('<p>用于批量将图片插入到Word文档中。工具根据文档中的序号段落自动匹配同名文件夹中的图片（图片文件名需为数字序号），并将图片插入到对应序号段落下方的空行位置。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/image-34.png" alt=""></p><h2 id="功能特点" tabindex="-1">功能特点 <a class="header-anchor" href="#功能特点" aria-label="Permalink to &quot;功能特点&quot;">​</a></h2><ul><li>批量处理文件夹中的所有Word文档（.docx格式）</li><li>自动识别文档中的序号段落（如“<strong>1、段落标题</strong>”）</li><li>根据序号匹配同名文件夹中的图片文件（图片名需为数字，如1.jpg, 2.png等）</li><li>将图片插入到对应序号段落下方的空行位置</li><li>支持穿透子文件夹（递归处理）</li></ul><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><ol><li><strong>文档解析</strong>：工具读取Word文档，识别格式为“数字+分隔符+内容”的段落（<strong>如“1、引言”、“2. 方法”等</strong>）。</li><li><strong>图片匹配</strong>：在文档所在文件夹或同名文件夹中查找图片文件，图片文件名应为纯数字（如1.jpg, 2.png），与文档中的序号对应。</li><li><strong>图片插入</strong>：将匹配的图片插入到对应序号段落下方的第一个空行位置，并删除该空行。</li><li><strong>输出结果</strong>：处理后的文档保存为“1.docx”（位于原文档所在文件夹）。</li></ol><h2 id="文件结构示例" tabindex="-1">文件结构示例 <a class="header-anchor" href="#文件结构示例" aria-label="Permalink to &quot;文件结构示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>项目文件夹/├── 文档1.docx├── 文档1/          （与文档同名的文件夹）│   ├── 1.jpg│   ├── 2.png│   └── 3.jpeg├── 文档2.docx└── 图片文件夹/    ├── 1.jpg    ├── 2.png    └── 3.jpeg</span></span></code></pre></div><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>仅支持<code>.docx</code>格式的Word文档</li><li>图片文件名必须为纯数字（<strong>如1.jpg, 2.png</strong>），不带扩展名以外的其他字符</li><li>文档中的序号段落格式应为“数字+分隔符+内容”，分隔符可以是空格、中文空格、顿号、逗号、句点等</li><li>程序会生成新的文档“1.docx”，原始文档不会被修改</li></ul><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2764.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2764.html</a></p>',12)])])}const _=a(l,[["render",n]]);export{h as __pageData,_ as default};
